vec3 flameRGB(float t) {
    return vec3(t, t*t, t*t*t);
}

void mainImage(out vec4 o, in vec2 p) {
    o = vec4(0,0,0,1);

    vec4 e = texture(iChannel1, p/iResolution.xy);

    o.rgb += RGB_2 * flameRGB(e.r);
    o.rgb += RGB_1 * flameRGB(e.g);

    o.rgb = pow(o.rgb, vec3(0.4545));

}

const float PI = radians(180.);
const float SQ3 = sqrt(3.);
const float INF = 1e10;

// Simulation consts
const int N_MAX = 128;
const int M = 4;
const float MASS = 50.0;

// Rendering consts
const vec3 RGB_1 = vec3(0.2, 0.1, 1.5);
const vec3 RGB_2 = vec3(1.5, 0.5, 0.2);
const float GLOW = 1.5;
const float R0 = 0.02;
const float R1 = 0.8;

int texSize(sampler2D ch0) {
    return min(N_MAX, textureSize(ch0, 0).x);
}

vec3 texFetch(sampler2D ch0, ivec2 p) {
    int N = texSize(ch0);
    p = ivec2(mod(vec2(p), vec2(ivec2(N,M*2))));
    return texelFetch(ch0, p, 0).xyz;
}

// Simulates the motion of masses in iChannel0.

void mainImage(out vec4 o, in vec2 p) {
    int N = texSize(iChannel0);
    ivec2 pp = ivec2(p - 0.5);

    if (pp.x > N-1 || pp.y > M*2-1)
        return;

    float ps = 1.0 - 0.01*float(pp.y/2);

    // initial state
    if (iFrame == 0) {
        float phi = 2.*PI*float(p.x)/float(N);
        phi += 0.02*sin(2.*PI/float(M)*float(pp.y/2));
        float x = cos(phi);
        float y = sin(phi);
        float z = -0.5 + 2.0 * sin(phi * 4.0) + 0.1 * sin(phi * 64.0);
        o.xyz = normalize(vec3(x,y,z));
        return;
    }

    // prev <- curr
    if (pp.y % 2 == 1) {
        o = texelFetch(iChannel0, pp - ivec2(0,1), 0);
        return;
    }

    vec3 cc = texFetch(iChannel0, pp); // length(cc) = 1
    vec3 cc_prev = texFetch(iChannel0, pp + ivec2(0,1));
    vec3 rr = texFetch(iChannel0, pp + ivec2(1,0));
    vec3 ll = texFetch(iChannel0, pp - ivec2(1,0));
    vec3 uu = texFetch(iChannel0, pp + ivec2(0,2));
    vec3 dd = texFetch(iChannel0, pp - ivec2(0,2));

    vec3 T = rr + ll - 2.*cc; // Hooke's law
    T += (uu + dd - 2.*cc)*(1. + 0.5*(uu - dd)); 
    vec3 ds = cc - cc_prev + T/MASS;
    ds -= cc*dot(cc, ds); // make ds tangent to the unit sphere: dot(cc,ds) = 0
    o.xyz = normalize(cc + ds); // project cc+ds onto the unit sphere
}

// Renders the mesh defined by iChannel0 coords.

float lineSDF(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}

vec2 p2q(vec2 p) {
    vec2 ar = iResolution.xy/iResolution.yy;
    return (p/iResolution.xy*2. - 1.) * ar;
}

vec2 q2p(vec2 q) {
    vec2 ar = iResolution.xy/iResolution.yy;
    return (q/ar*0.5 + 0.5) * iResolution.xy;
}

vec2 pos(int i, int s) {
    vec3 r = texFetch(iChannel0, ivec2(i,2*s));
    return r.xy / (1.3 - r.z);
}

float sdf(vec2 q, int s) {
    int N = texSize(iChannel0);
    float d = INF, e = 0.;
    vec2 a = pos(-1,s);

    for (int i = 0; i < N; i++) {
        vec2 b = pos(i,s);
        d = min(d, lineSDF(q, a, b));
        a = b;
    }

    return d;
}

void mainImage(out vec4 o, vec2 p) {
    vec2 q = p2q(p);
    float e = 0.;

    o = vec4(0);

    for (int s = 0; s < M; s++)
        o.r += exp(-pow(7.5/R0*sdf(q/R1, s), 2.0));

    o.g = o.r;
    o.rg /= float(M);

    float dt = 0.02;
    o.r += (1.0-dt*1.0)*texture(iChannel1, q2p(q*(1.0-dt*0.3))/iResolution.xy).r;
    o.g += (1.0-dt*1.0)*texture(iChannel1, q2p(q*(1.0+dt*0.3))/iResolution.xy).g;
}
